
CREATE TABLE `tmp_spell_effective` AS SELECT `entry`, `school`, `category`, `dispel`, `mechanic`, `attributes`, `attributesEx`, `attributesEx2`, `attributesEx3`, `attributesEx4`, `stances`, `stancesNot`, `targets`, `targetCreatureType`, `requiresSpellFocus`, `casterAuraState`, `targetAuraState`, `castingTimeIndex`, `recoveryTime`, `categoryRecoveryTime`, `interruptFlags`, `auraInterruptFlags`, `channelInterruptFlags`, `procFlags`, `procChance`, `procCharges`, `maxLevel`, `baseLevel`, `spellLevel`, `durationIndex`, `powerType`, `manaCost`, `manCostPerLevel`, `manaPerSecond`, `manaPerSecondPerLevel`, `rangeIndex`, `speed`, `modelNextSpell`, `stackAmount`, `totem1`, `totem2`, `reagent1`, `reagent2`, `reagent3`, `reagent4`, `reagent5`, `reagent6`, `reagent7`, `reagent8`, `reagentCount1`, `reagentCount2`, `reagentCount3`, `reagentCount4`, `reagentCount5`, `reagentCount6`, `reagentCount7`, `reagentCount8`, `equippedItemClass`, `equippedItemSubClassMask`, `equippedItemInventoryTypeMask`, `name`, `nameSubtext`, `description`, `auraDescription`, `manaCostPercentage`, `startRecoveryCategory`, `startRecoveryTime`, `minTargetLevel`, `maxTargetLevel`, `spellFamilyName`, `spellFamilyFlags`, `maxAffectedTargets`, `dmgClass`, `preventionType`, `stanceBarOrder`, `minFactionId`, `minReputation`, `requiredAuraVision`, `customFlags`, `script_name` FROM `spell_template`;
UPDATE `tmp_spell_effective` AS t SET `procChance` = CASE WHEN m.`procChance` >= 0 THEN m.`procChance` ELSE t.`procChance` END, `procFlags` = CASE WHEN m.`procFlags` >= 0 THEN m.`procFlags` ELSE t.`procFlags` END, `procCharges` = CASE WHEN m.`procCharges` >= 0 THEN m.`procCharges` ELSE t.`procCharges` END, `durationIndex` = CASE WHEN m.`durationIndex` >= 0 THEN m.`durationIndex` ELSE t.`durationIndex` END, `category` = CASE WHEN m.`category` >= 0 THEN m.`category` ELSE t.`category` END, `castingTimeIndex` = CASE WHEN m.`castingTimeIndex` >= 0 THEN m.`castingTimeIndex` ELSE t.`castingTimeIndex` END, `stackAmount` = CASE WHEN m.`stackAmount` >= 0 THEN m.`stackAmount` ELSE t.`stackAmount` END, `manaCost` = CASE WHEN m.`manaCost` >= 0 THEN m.`manaCost` ELSE t.`manaCost` END, `attributes` = CASE WHEN m.`attributes` >= 0 THEN m.`attributes` ELSE t.`attributes` END, `attributesEx` = CASE WHEN m.`attributesEx` >= 0 THEN m.`attributesEx` ELSE t.`attributesEx` END, `attributesEx2` = CASE WHEN m.`attributesEx2` >= 0 THEN m.`attributesEx2` ELSE t.`attributesEx2` END, `attributesEx3` = CASE WHEN m.`attributesEx3` >= 0 THEN m.`attributesEx3` ELSE t.`attributesEx3` END, `attributesEx4` = CASE WHEN m.`attributesEx4` >= 0 THEN m.`attributesEx4` ELSE t.`attributesEx4` END, `interruptFlags` = CASE WHEN m.`interruptFlags` >= 0 THEN m.`interruptFlags` ELSE t.`interruptFlags` END, `auraInterruptFlags` = CASE WHEN m.`auraInterruptFlags` >= 0 THEN m.`auraInterruptFlags` ELSE t.`auraInterruptFlags` END, `channelInterruptFlags` = CASE WHEN m.`channelInterruptFlags` >= 0 THEN m.`channelInterruptFlags` ELSE t.`channelInterruptFlags` END, `dispel` = CASE WHEN m.`dispel` >= 0 THEN m.`dispel` ELSE t.`dispel` END, `stances` = CASE WHEN m.`stances` >= 0 THEN m.`stances` ELSE t.`stances` END, `stancesNot` = CASE WHEN m.`stancesNot` >= 0 THEN m.`stancesNot` ELSE t.`stancesNot` END, `manaCostPercentage` = CASE WHEN m.`manaCostPercentage` >= 0 THEN m.`manaCostPercentage` ELSE t.`manaCostPercentage` END, `startRecoveryCategory` = CASE WHEN m.`startRecoveryCategory` >= 0 THEN m.`startRecoveryCategory` ELSE t.`startRecoveryCategory` END, `startRecoveryTime` = CASE WHEN m.`startRecoveryTime` >= 0 THEN m.`startRecoveryTime` ELSE t.`startRecoveryTime` END, `maxTargetLevel` = CASE WHEN m.`maxTargetLevel` >= 0 THEN m.`maxTargetLevel` ELSE t.`maxTargetLevel` END, `maxAffectedTargets` = CASE WHEN m.`maxAffectedTargets` >= 0 THEN m.`maxAffectedTargets` ELSE t.`maxAffectedTargets` END, `dmgClass` = CASE WHEN m.`dmgClass` >= 0 THEN m.`dmgClass` ELSE t.`dmgClass` END, `rangeIndex` = CASE WHEN m.`rangeIndex` >= 0 THEN m.`rangeIndex` ELSE t.`rangeIndex` END, `recoveryTime` = CASE WHEN m.`recoveryTime` >= 0 THEN m.`recoveryTime` ELSE t.`recoveryTime` END, `categoryRecoveryTime` = CASE WHEN m.`categoryRecoveryTime` >= 0 THEN m.`categoryRecoveryTime` ELSE t.`categoryRecoveryTime` END, `spellFamilyName` = CASE WHEN m.`spellFamilyName` >= 0 THEN m.`spellFamilyName` ELSE t.`spellFamilyName` END, `mechanic` = CASE WHEN m.`mechanic` >= 0 THEN m.`mechanic` ELSE t.`mechanic` END, `equippedItemClass` = CASE WHEN m.`EquippedItemClass` <> -1 THEN m.`EquippedItemClass` ELSE t.`equippedItemClass` END, `spellFamilyFlags` = CASE WHEN m.`SpellFamilyFlags` <> 0 THEN m.`SpellFamilyFlags` ELSE t.`spellFamilyFlags` END, `customFlags` = CASE WHEN m.`Custom` <> 0 THEN m.`Custom` ELSE t.`customFlags` END FROM `spell_mod` m WHERE m.`Id` = t.`entry`;
UPDATE `tmp_spell_effective` SET `speed` = 0 WHERE `entry` = 1543;
UPDATE `tmp_spell_effective` SET `speed` = 10 WHERE `entry` = 20424;
CREATE TABLE `tmp_spell_effect_effective` (`spell_id` INTEGER NOT NULL, `effect_index` INTEGER NOT NULL, `effect` INTEGER, `effectDieSides` INTEGER, `effectBaseDice` INTEGER, `effectDicePerLevel` REAL, `effectRealPointsPerLevel` REAL, `effectBasePoints` INTEGER, `effectBonusCoefficient` REAL, `effectMechanic` INTEGER, `effectImplicitTargetA` INTEGER, `effectImplicitTargetB` INTEGER, `effectRadiusIndex` INTEGER, `effectApplyAuraName` INTEGER, `effectAmplitude` INTEGER, `effectMultipleValue` REAL, `effectChainTarget` INTEGER, `effectItemType` INTEGER, `effectMiscValue` INTEGER, `effectTriggerSpell` INTEGER, `effectPointsPerComboPoint` REAL, `dmgMultiplier` REAL, PRIMARY KEY(`spell_id`, `effect_index`));
UPDATE `tmp_spell_effect_effective` AS t SET `Effect` = CASE WHEN m.`Effect` >= 0 THEN m.`Effect` ELSE t.`Effect` END, `EffectApplyAuraName` = CASE WHEN m.`EffectApplyAuraName` >= 0 THEN m.`EffectApplyAuraName` ELSE t.`EffectApplyAuraName` END, `EffectMechanic` = CASE WHEN m.`EffectMechanic` >= 0 THEN m.`EffectMechanic` ELSE t.`EffectMechanic` END, `EffectImplicitTargetA` = CASE WHEN m.`EffectImplicitTargetA` >= 0 THEN m.`EffectImplicitTargetA` ELSE t.`EffectImplicitTargetA` END, `EffectImplicitTargetB` = CASE WHEN m.`EffectImplicitTargetB` >= 0 THEN m.`EffectImplicitTargetB` ELSE t.`EffectImplicitTargetB` END, `EffectRadiusIndex` = CASE WHEN m.`EffectRadiusIndex` >= 0 THEN m.`EffectRadiusIndex` ELSE t.`EffectRadiusIndex` END, `EffectTriggerSpell` = CASE WHEN m.`EffectTriggerSpell` >= 0 THEN m.`EffectTriggerSpell` ELSE t.`EffectTriggerSpell` END, `EffectBaseDice` = CASE WHEN m.`EffectBaseDice` >= 0 THEN m.`EffectBaseDice` ELSE t.`EffectBaseDice` END, `EffectAmplitude` = CASE WHEN m.`EffectAmplitude` >= 0 THEN m.`EffectAmplitude` ELSE t.`EffectAmplitude` END, `EffectChainTarget` = CASE WHEN m.`EffectChainTarget` >= 0 THEN m.`EffectChainTarget` ELSE t.`EffectChainTarget` END, `EffectItemType` = CASE WHEN m.`EffectItemType` >= 0 THEN m.`EffectItemType` ELSE t.`EffectItemType` END, `EffectMiscValue` = CASE WHEN m.`EffectMiscValue` <> -1 THEN m.`EffectMiscValue` ELSE t.`EffectMiscValue` END, `EffectDieSides` = CASE WHEN m.`EffectDieSides` <> -1 THEN m.`EffectDieSides` ELSE t.`EffectDieSides` END, `EffectBasePoints` = CASE WHEN m.`EffectBasePoints` <> -1 THEN m.`EffectBasePoints` ELSE t.`EffectBasePoints` END, `EffectDicePerLevel` = CASE WHEN m.`EffectDicePerLevel` <> -1.0 THEN m.`EffectDicePerLevel` ELSE t.`EffectDicePerLevel` END, `EffectRealPointsPerLevel` = CASE WHEN m.`EffectRealPointsPerLevel` <> -1.0 THEN m.`EffectRealPointsPerLevel` ELSE t.`EffectRealPointsPerLevel` END, `EffectPointsPerComboPoint` = CASE WHEN m.`EffectPointsPerComboPoint` <> -1.0 THEN m.`EffectPointsPerComboPoint` ELSE t.`EffectPointsPerComboPoint` END, `EffectMultipleValue` = CASE WHEN m.`EffectMultipleValue` <> -1.0 THEN m.`EffectMultipleValue` ELSE t.`EffectMultipleValue` END FROM `spell_effect_mod` m WHERE m.`Id` = t.`spell_id` AND m.`EffectIndex` = t.`effect_index`;
UPDATE `tmp_spell_effect_effective` SET `effectItemType` = 0x80202000 WHERE `spell_id` = 20216 AND `effect_index` = 0;
CREATE TABLE `spell_extra`( `spell_id` INTEGER NOT NULL DEFAULT 0, `custom_flags` INTEGER NOT NULL DEFAULT 0, `script_name` TEXT NOT NULL DEFAULT '' COLLATE NOCASE, `min_target_level` INTEGER NOT NULL DEFAULT 0, `effect_base_dice1` INTEGER DEFAULT NULL, `effect_base_dice2` INTEGER DEFAULT NULL, `effect_base_dice3` INTEGER DEFAULT NULL, `effect_dice_per_level1` REAL NOT NULL DEFAULT 0, `effect_dice_per_level2` REAL NOT NULL DEFAULT 0, `effect_dice_per_level3` REAL NOT NULL DEFAULT 0, `default_coefficient1` INTEGER NOT NULL DEFAULT 0, `default_coefficient2` INTEGER NOT NULL DEFAULT 0, `default_coefficient3` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`spell_id`));
